create extension if not exists pgcrypto;
create schema auth;
create schema app_private;
create role anon;
create role authenticated;
create role service_role;
create table auth.users (id uuid primary key, email text, email_confirmed_at timestamptz);
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('request.jwt.claim.sub', true),'')::uuid $$;
create function auth.role() returns text language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claim.role', true),''),'authenticated') $$;
create table public.companies (id uuid primary key default gen_random_uuid(), legal_name text not null, status text not null default 'active');
create table public.branches (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.companies(id), code text not null, name text not null, status text not null default 'active', unique(tenant_id,id));
create table public.company_memberships (id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.companies(id), user_id uuid not null references auth.users(id), status text not null, branch_access_mode text not null, created_by_user_id uuid not null references auth.users(id), unique(tenant_id,id), unique(tenant_id,user_id));
create table public.branch_access (id uuid primary key default gen_random_uuid(), tenant_id uuid not null, branch_id uuid not null, membership_id uuid not null, status text not null, granted_by_user_id uuid not null references auth.users(id), unique(membership_id,branch_id));
create table public.permission_definitions (permission_key text primary key, description text not null, approval_state text not null default 'pending_approval');
create table public.access_role_definitions (role_key text primary key, display_name text not null, scope text not null, approval_state text not null default 'pending_approval');
create table public.role_permission_grants (role_key text not null references public.access_role_definitions(role_key), permission_key text not null references public.permission_definitions(permission_key), primary key(role_key,permission_key));
create table public.membership_role_assignments (id uuid primary key default gen_random_uuid(),tenant_id uuid not null,membership_id uuid not null,role_key text not null references public.access_role_definitions(role_key),branch_id uuid,assigned_by_user_id uuid not null references auth.users(id));
create table public.erp_transaction_authorization_catalog (transaction_code text primary key,module_code text not null,permission_key text not null references public.permission_definitions(permission_key),approval_state text not null default 'pending_approval',created_at timestamptz not null default now());
create table app_private.provisioning_audit_events (id uuid primary key default gen_random_uuid(),event_key text not null,tenant_id uuid,subject_user_id uuid,actor_user_id uuid,actor_database_role text,actor_api_role text,details jsonb default '{}'::jsonb,created_at timestamptz not null default now());
create function app_private.is_active_company_member(uuid) returns boolean language sql stable as $$ select true $$;
create function app_private.can_access_branch(uuid,uuid) returns boolean language sql stable as $$ select true $$;
create function app_private.has_tenant_permission(uuid,text,uuid default null) returns boolean language sql stable as $$ select true $$;
create function app_private.write_provisioning_audit(text,uuid,uuid,uuid,jsonb) returns void language sql as $$ insert into app_private.provisioning_audit_events(event_key,tenant_id,subject_user_id,actor_user_id,details) values($1,$2,$3,$4,$5) $$;
